class Solution:
    def solve(self, spec_path: str = None) -> dict:
        code = r'''
import networkx as nx
from collections import defaultdict
import random
import math

class BroadCastTopology:
    def __init__(self, src: str, dsts: list, num_partitions: int):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst: str, partition: int, path: list):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst: str, partition: int, paths: list):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    num_vms = 2
    instance_rate = 0.54

    ingress_limit_map = {"aws": 10, "gcp": 16, "azure": 16}
    egress_limit_map = {"aws": 5, "gcp": 7, "azure": 16}

    def get_provider(node):
        return node.split(":")[0] if ":" in node else "aws"

    def get_node_egress_gbps(node):
        provider = get_provider(node)
        return egress_limit_map.get(provider, 5) * num_vms

    def get_node_ingress_gbps(node):
        provider = get_provider(node)
        return ingress_limit_map.get(provider, 10) * num_vms

    data_vol_gb = 300.0
    if hasattr(G, 'graph'):
        if 'data_vol' in G.graph:
            data_vol_gb = float(G.graph['data_vol'])
        if 'num_vms' in G.graph:
            num_vms = int(G.graph['num_vms'])

    partition_size_gb = data_vol_gb / num_partitions

    def path_edges_list(path):
        edges = []
        for i in range(len(path) - 1):
            edges.append([path[i], path[i+1], dict(G[path[i]][path[i+1]])])
        return edges

    # Compute cost given assignment: {dst: {p: node_path_list}}
    def compute_cost(dst_part_paths):
        edge_load = defaultdict(int)  # (u,v) -> number of partition-flows
        node_out = defaultdict(set)
        node_in = defaultdict(set)
        nodes_used = set()

        for dst in dsts:
            for p in range(num_partitions):
                node_path = dst_part_paths.get(dst, {}).get(p)
                if node_path is None:
                    continue
                for i in range(len(node_path) - 1):
                    u, v = node_path[i], node_path[i+1]
                    edge_load[(u, v)] += 1
                    node_out[u].add((u, v))
                    node_in[v].add((u, v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_load:
            return float('inf')

        egress_cost = 0.0
        for (u, v), count in edge_load.items():
            c = G[u][v].get("cost", 0.0)
            egress_cost += count * partition_size_gb * c

        max_time = 0.0
        for (u, v), count in edge_load.items():
            tp = G[u][v].get("throughput", 1.0)
            n_out = len(node_out[u])
            n_in = len(node_in[v])
            eg = get_node_egress_gbps(u) / max(n_out, 1)
            ig = get_node_ingress_gbps(v) / max(n_in, 1)
            bw = min(tp, eg, ig)
            if bw <= 0:
                bw = 0.001
            data_gb = count * partition_size_gb
            t = data_gb * 8.0 / bw
            max_time = max(max_time, t)

        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_time
        return egress_cost + inst_cost

    # Build candidate paths per destination
    K_PATHS = 40
    dst_candidates = {}
    for dst in dsts:
        cands = []
        try:
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, path in enumerate(gen):
                if i >= K_PATHS:
                    break
                cands.append(path)
        except:
            pass

        # Add shortest hop path
        try:
            sp = nx.shortest_path(G, src, dst)
            if sp not in cands:
                cands.append(sp)
        except:
            pass

        # Add max-throughput path
        try:
            tp_path = nx.dijkstra_path(G, src, dst, weight=lambda u, v, d: 1.0 / max(d.get("throughput", 0.001), 0.001))
            if tp_path not in cands:
                cands.append(tp_path)
        except:
            pass

        # Add weighted paths
        for lam in [0.001, 0.01, 0.05, 0.1, 0.5, 1.0, 5.0]:
            try:
                wp = nx.dijkstra_path(G, src, dst, weight=lambda u, v, d, l=lam: d.get("cost", 0) + l / max(d.get("throughput", 0.001), 0.001))
                if wp not in cands:
                    cands.append(wp)
            except:
                pass

        dst_candidates[dst] = cands

    # Helper: build dst_part_paths from assignment
    def build_paths(assignment):
        result = {}
        for dst in dsts:
            result[dst] = {}
            cands = dst_candidates.get(dst, [])
            for p in range(num_partitions):
                idx = assignment.get((dst, p), 0)
                if cands and idx < len(cands):
                    result[dst][p] = cands[idx]
                elif cands:
                    result[dst][p] = cands[0]
                else:
                    result[dst][p] = None
        return result

    def eval_assignment(assignment):
        return compute_cost(build_paths(assignment))

    # ================================================================
    # Strategy: All same path per dst, try each candidate
    # ================================================================
    def strategy_single_path():
        best_a = {}
        best_c = float('inf')

        # For each combination would be too expensive; try each dst independently first
        # then refine

        # First pass: pick best single path for each dst ignoring interactions
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            best_idx = 0
            best_cost = float('inf')
            for idx, path in enumerate(cands):
                c = sum(G[path[i]][path[i+1]].get("cost", 0) for i in range(len(path)-1))
                if c < best_cost:
                    best_cost = c
                    best_idx = idx
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx

        return assignment

    # ================================================================
    # Strategy: Steiner tree approach - share intermediate nodes
    # ================================================================
    def strategy_steiner():
        assignment = {}
        tree_nodes = {src}
        tree_edges = set()
        dst_paths_map = {}
        remaining = list(dsts)

        while remaining:
            best_dst = None
            best_path = None
            best_score = float('inf')

            for dst in remaining:
                for tn in tree_nodes:
                    try:
                        path = nx.shortest_path(G, tn, dst, weight="cost")
                        cost = sum(G[path[i]][path[i+1]].get("cost", 0) for i in range(len(path)-1))
                        new_nodes = sum(1 for n in path if n not in tree_nodes)
                        score = cost + new_nodes * 0.5
                        if score < best_score:
                            best_score = score
                            best_path = (tn, path)
                            best_dst = dst
                    except:
                        pass

            if best_dst is None:
                remaining.pop(0) if remaining else None
                continue

            remaining.remove(best_dst)
            tn, path = best_path
            for n in path:
                tree_nodes.add(n)
            for i in range(len(path)-1):
                tree_edges.add((path[i], path[i+1]))

            # Build full path from src through tree
            try:
                tree_g = nx.DiGraph()
                for u, v in tree_edges:
                    tree_g.add_edge(u, v, **dict(G[u][v]))
                full_path = nx.shortest_path(tree_g, src, best_dst, weight="cost")
                dst_paths_map[best_dst] = full_path
            except:
                cands = dst_candidates.get(best_dst, [])
                if cands:
                    dst_paths_map[best_dst] = cands[0]

        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            path = dst_paths_map.get(dst)
            idx = 0
            if path and cands:
                for ci, cp in enumerate(cands):
                    if cp == path:
                        idx = ci
                        break
                else:
                    cands.append(path)
                    idx = len(cands) - 1
            for p in range(num_partitions):
                assignment[(dst, p)] = idx

        return assignment

    # ================================================================
    # Strategy: Spread partitions across multiple paths per dst
    # ================================================================
    def strategy_spread(n_paths):
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            n_use = min(len(cands), n_paths)
            for p in range(num_partitions):
                assignment[(dst, p)] = p % n_use
        return assignment

    # ================================================================
    # Strategy: Minimize nodes used (fewest hops)
    # ================================================================
    def strategy_min_hops():
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            best_idx = min(range(len(cands)), key=lambda i: len(cands[i]))
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx
        return assignment

    # ================================================================
    # Strategy: Pick path per dst considering both cost and instance cost
    # ================================================================
    def strategy_joint_opt():
        assignment = {}
        # Try each candidate for each dst, considering global cost
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            for p in range(num_partitions):
                assignment[(dst, p)] = 0

        # Iterate: for each dst, try swapping all partitions to a different path
        improved = True
        rounds = 0
        current_cost = eval_assignment(assignment)

        while improved and rounds < 10:
            improved = False
            rounds += 1
            for dst in dsts:
                cands = dst_candidates.get(dst, [])
                if not cands or len(cands) <= 1:
                    continue

                current_idx = assignment[(dst, 0)]
                best_idx = current_idx
                best_c = current_cost

                for idx in range(min(len(cands), 20)):
                    if idx == current_idx:
                        continue
                    for p in range(num_partitions):
                        assignment[(dst, p)] = idx
                    c = eval_assignment(assignment)
                    if c < best_c:
                        best_c = c
                        best_idx = idx

                for p in range(num_partitions):
                    assignment[(dst, p)] = best_idx

                if best_idx != current_idx:
                    current_cost = best_c
                    improved = True

        return assignment

    # ================================================================
    # Strategy: Joint opt with partition spreading
    # For each dst, try: all on one path, or spread across 2-3 paths
    # ================================================================
    def strategy_joint_spread():
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            for p in range(num_partitions):
                assignment[(dst, p)] = 0

        current_cost = eval_assignment(assignment)

        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue

            best_config = [(dst, p, 0) for p in range(num_partitions)]
            best_c = current_cost

            # Try single path options
            for idx in range(min(len(cands), 15)):
                for p in range(num_partitions):
                    assignment[(dst, p)] = idx
                c = eval_assignment(assignment)
                if c < best_c:
                    best_c = c
                    best_config = [(dst, p, idx) for p in range(num_partitions)]

            # Try spreading across pairs
            for i in range(min(len(cands), 8)):
                for j in range(i+1, min(len(cands), 8)):
                    for p in range(num_partitions):
                        assignment[(dst, p)] = i if p % 2 == 0 else j
                    c = eval_assignment(assignment)
                    if c < best_c:
                        best_c = c
                        best_config = [(dst, p, i if p % 2 == 0 else j) for p in range(num_partitions)]

            # Try spreading across triples
            if len(cands) >= 3:
                for i in range(min(len(cands), 5)):
                    for j in range(i+1, min(len(cands), 5)):
                        for k in range(j+1, min(len(cands), 5)):
                            choices = [i, j, k]
                            for p in range(num_partitions):
                                assignment[(dst, p)] = choices[p % 3]
                            c = eval_assignment(assignment)
                            if c < best_c:
                                best_c = c
                                best_config = [(dst, p, choices[p % 3]) for p in range(num_partitions)]

            for _, p, idx in best_config:
                assignment[(dst, p)] = idx
            current_cost = best_c

        return assignment

    # ================================================================
    # Evaluate strategies
    # ================================================================
    strategies = [
        ("single_path", strategy_single_path),
        ("steiner", strategy_steiner),
        ("min_hops", strategy_min_hops),
        ("spread2", lambda: strategy_spread(2)),
        ("spread3", lambda: strategy_spread(3)),
        ("spread4", lambda: strategy_spread(4)),
        ("spread5", lambda: strategy_spread(5)),
        ("joint_opt", strategy_joint_opt),
    ]

    best_assignment = None
    best_cost = float('inf')

    for name, fn in strategies:
        try:
            a = fn()
            c = eval_assignment(a)
            if c < best_cost:
                best_cost = c
                best_assignment = dict(a)
        except:
            pass

    # Try joint spread (more expensive)
    n_items = num_partitions * len(dsts)
    if n_items <= 500:
        try:
            a = strategy_joint_spread()
            c = eval_assignment(a)
            if c < best_cost:
                best_cost = c
                best_assignment = dict(a)
        except:
            pass

    if best_assignment is None:
        best_assignment = {}
        for dst in dsts:
            for p in range(num_partitions):
                best_assignment[(dst, p)] = 0

    # ================================================================
    # Simulated annealing
    # ================================================================
    random.seed(42)
    current = dict(best_assignment)
    current_cost = best_cost
    sa_best = dict(best_assignment)
    sa_best_cost = best_cost

    all_keys = [(dst, p) for dst in dsts for p in range(num_partitions)]

    temp = max(best_cost * 0.02, 0.5)
    cooling = 0.998
    max_iters = min(8000, n_items * 30)

    for it in range(max_iters):
        if not all_keys:
            break

        key = random.choice(all_keys)
        dst, p = key
        cands = dst_candidates.get(dst, [])
        if not cands or len(cands) <= 1:
            continue

        old_idx = current.get(key, 0)
        new_idx = random.randint(0, len(cands) - 1)
        if new_idx == old_idx:
            continue

        saved = current[key]
        current[key] = new_idx
        new_cost = eval_assignment(current)
        delta = new_cost - current_cost

        if delta < 0 or (temp > 0 and random.random() < math.exp(-delta / max(temp, 1e-10))):
            current_cost = new_cost
            if current_cost < sa_best_cost:
                sa_best_cost = current_cost
                sa_best = dict(current)
        else:
            current[key] = saved

        temp *= cooling

    if sa_best_cost < best_cost:
        best_assignment = sa_best
        best_cost = sa_best_cost

    # ================================================================
    # Hill climbing
    # ================================================================
    improved = True
    hc_rounds = 0
    while improved and hc_rounds < 5:
        improved = False
        hc_rounds += 1

        # Per-dst: try swapping all partitions to same path
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands or len(cands) <= 1:
                continue

            saved = {(dst, p): best_assignment.get((dst, p), 0) for p in range(num_partitions)}

            for idx in range(min(len(cands), 20)):
                for p in range(num_partitions):
                    best_assignment[(dst, p)] = idx
                c = eval_assignment(best_assignment)
                if c < best_cost:
                    best_cost = c
                    saved = {(dst, p): idx for p in range(num_partitions)}
                    improved = True

            for k, v in saved.items():
                best_assignment[k] = v

        # Per partition-key
        for key in all_keys:
            dst, p = key
            cands = dst_candidates.get(dst, [])
            if not cands or len(cands) <= 1:
                continue

            old_idx = best_assignment.get(key, 0)
            best_idx = old_idx

            for idx in range(min(len(cands), 20)):
                if idx == old_idx:
                    continue
                best_assignment[key] = idx
                c = eval_assignment(best_assignment)
                if c < best_cost:
                    best_cost = c
                    best_idx = idx
                    improved = True

            best_assignment[key] = best_idx

    # ================================================================
    # Build topology
    # ================================================================
    for dst in dsts:
        cands = dst_candidates.get(dst, [])
        if not cands:
            continue
        for p in range(num_partitions):
            idx = best_assignment.get((dst, p), 0)
            if idx >= len(cands):
                idx = 0
            path = cands[idx]
            edges = path_edges_list(path)
            bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology
